grid[10].append(8)
from collections import deque,defaultdict
R,C=len(grid),len(grid[0])
def comps(col):
 seen=set(); out=[]
 for r in range(R):
  for c in range(C):
   if grid[r][c]!=col or (r,c) in seen: continue
   q=[(r,c)];seen.add((r,c));cells=[]
   while q:
    p=q.pop();cells.append(p)
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
     x,y=p[0]+dr,p[1]+dc
     if 0<=x<R and 0<=y<C and grid[x][y]==col and (x,y) not in seen:seen.add((x,y));q.append((x,y))
   out.append(cells)
 return out
def norm(cells):
 mr=min(r for r,c in cells);mc=min(c for r,c in cells)
 return tuple(sorted((r-mr,c-mc) for r,c in cells))
def canon(cells,rot=True,ref=True):
 pts=norm(cells); forms=[]
 for flip in ([1,-1] if ref else [1]):
  for k in range(4 if rot else 1):
   vals=[]
   for r,c in pts:
    x,y=r, c*flip
    for _ in range(k): x,y=y,-x
    vals.append((x,y))
   mr=min(x for x,y in vals);mc=min(y for x,y in vals)
   forms.append(tuple(sorted((x-mr,y-mc) for x,y in vals)))
 return min(forms)
